```svelte
<script lang="ts">
  import { $state, $effect } from 'svelte/runes';

  const number = $state(5);

  let doubled = $effect(
    () => number,
    () => {
      doubled = number * 2;
    }
  );
</script>

<div>
  <p data-testid="number-value">Number: {number}</p>
  <p data-testid="doubled-value">Doubled: {doubled}</p>
  <button data-testid="increment-button" onclick={() => (number += 1)}>Increment</button>
</div>
```

