```svelte
<script lang="ts">
  import { snippet } from 'svelte/snippet';
  const books = ['The Lord of the Rings', 'To Kill a Mockingbird', '1984'];
  const title = ($title: string) => <span data-testid="book-title">{title}</span>;
  let { books } = $state(books);
</script>

<ul>
  {#each $books as book}
    <li data-testid="book-item">
      {#snippet title($title: string)}
        {title(book)}
      {/snippet}
    </li>
  {/each}
</ul>
